{
  "status": "SUPPORTED",
  "task_summary": "Find fastening parts in storage, attach them to a base object on the workbench, and leave the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The flat area where the task is performed and tools are left.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "table",
          "desk",
          "wooden surface"
        ],
        "required_properties": [
          "flat",
          "horizontal",
          "stable"
        ]
      },
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific location on the workbench where the fastening must occur.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "marked spot",
          "attachment point",
          "hole"
        ],
        "required_properties": [
          "accessible",
          "fixed"
        ]
      },
      {
        "id": "base_object",
        "entity_kind": "OBJECT",
        "function": "The object currently on the workbench that needs to be fastened.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "fixture",
          "part",
          "block",
          "assembly"
        ],
        "required_properties": [
          "has attachment interface",
          "sits on workbench"
        ]
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The missing part required to complete the fastening.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "screw",
          "bolt",
          "nut",
          "clip",
          "bracket"
        ],
        "required_properties": [
          "fits base_object",
          "compatible with fastening_target"
        ]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to perform the fastening.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "hammer",
          "hand tool"
        ],
        "required_properties": [
          "implements fastening",
          "reusable"
        ]
      },
      {
        "id": "storage_unit",
        "entity_kind": "OBJECT",
        "function": "Enclosed spaces where components might be hidden.",
        "required_count": 3,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "drawer",
          "cabinet",
          "compartment"
        ],
        "required_properties": [
          "enclosed",
          "accessible",
          "can be opened"
        ]
      },
      {
        "id": "robot_arm",
        "entity_kind": "OBJECT",
        "function": "The manipulator performing the task.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "robotic arm",
          "manipulator",
          "gripper"
        ],
        "required_properties": [
          "capable of grasping",
          "capable of moving"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "fits_with",
        "relation": "compatible_component fits_with base_object",
        "participant_roles": [
          "compatible_component",
          "base_object"
        ]
      ,
        "required": true
      },
      {
        "id": "used_at",
        "relation": "fastening_tool used_at fastening_target",
        "participant_roles": [
          "fastening_tool",
          "fastening_target"
        ]
      ,
        "required": true
      },
      {
        "id": "must_remain_on",
        "relation": "fastening_tool must_remain_on workbench_surface",
        "participant_roles": [
          "fastening_tool",
          "workbench_surface"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_and_identify",
        "operation": "search_and_identify",
        "participant_roles": [
          "robot_arm",
          "storage_unit",
          "compatible_component"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "fasten",
        "operation": "fasten",
        "participant_roles": [
          "robot_arm",
          "fastening_tool",
          "base_object",
          "compatible_component"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "place_tool",
        "participant_roles": [
          "robot_arm",
          "fastening_tool",
          "workbench_surface"
        ]
      ,
        "operation_count": 1
      }
    ]
  }
,
